Rule.Source:
import java.util.Map;
import javax.naming.directory.DirContext;
import sailpoint.object.ResourceObject;

String ADMIN_LOCK = "000001010000Z";
String[] STATUS_ATTRS = { "pwdAccountLockedTime", "pwdChangedTime", "pwdFailureTime",
                          "createTimestamp", "modifyTimestamp" };

if (object == null || !"account".equals(object.getObjectType())) return object;

try {
    DirContext ldap = (state == null) ? null : (DirContext) state.get("hrLdapContext");
    if (ldap == null) {
        ldap = ldapConnect(context, application);
        if (state != null) state.put("hrLdapContext", ldap);
    }
    String dn = object.getIdentity();

    // 1. Groups
    object.setAttribute("groups", ldapGroupsOf(ldap, dn));

    // 2. Account status
    Map st = ldapReadAttributes(ldap, dn, STATUS_ATTRS);
    String lockedTime = (String) st.get("pwdAccountLockedTime");
    String status = "Active";
    if (lockedTime != null) {
        status = ADMIN_LOCK.equals(lockedTime) ? "Disabled" : "Locked";
    }
    object.setAttribute("accountStatus", status);
    object.setAttribute("pwdAccountLockedTime", lockedTime);   // raw value, empty when active
    object.setAttribute("IIQDisabled", Boolean.valueOf("Disabled".equals(status)));
    object.setAttribute("IIQLocked", Boolean.valueOf("Locked".equals(status)));
    object.setAttribute("lockedTime",
            (lockedTime == null || ADMIN_LOCK.equals(lockedTime)) ? null : ldapFormatTime(lockedTime));
    object.setAttribute("passwordLastChanged", ldapFormatTime((String) st.get("pwdChangedTime")));
    object.setAttribute("lastFailedLogin", ldapFormatTime((String) st.get("pwdFailureTime")));
    object.setAttribute("createdOn", ldapFormatTime((String) st.get("createTimestamp")));
    object.setAttribute("modifiedOn", ldapFormatTime((String) st.get("modifyTimestamp")));
} catch (Exception e) {
    log.error("LDAP ApacheDS: could not read groups/status for " + object.getIdentity() + ": " + e);
}
return object;
